mapper.select:
SELECT review_id, acm_name, content, created_at, rating FROM ( SELECT r.review_id review_id, a.acm_name acm_name, r.content content, r.created_at created_at, r.rating rating, ROW_NUMBER() OVER (ORDER BY r.review_id DESC) AS rnum FROM accommodation a JOIN review r ON a.acm_id = r.acm_id WHERE r.user_id = #{user_id}
AND INSTR(r.content, #{keyWord}) > 0
) WHERE rnum BETWEEN #{startNum} AND #{endNum}

mapper.update:
UPDATE review_img
SET
img_name = #{img_name}
WHERE
review_id = #{review_id};
